-- Traductions anglaises des exercices de 1ʳᵉ spécialité
-- ===========================================================================
--
-- 68 exercices, 71 variations, 94 champs traduits (énoncés et, quand elles
-- existent vraiment, solutions ; les solutions réduites au placeholder « a »
-- n'ont pas été traduites).
--
-- Le français reste la source de vérité : chaque UPDATE se contente d'AJOUTER
-- la clé translations.en dans la variation visée via jsonb_set. Aucun champ
-- français n'est réécrit — la traduction ne peut donc pas abîmer l'original.
--
-- VERROU OPTIMISTE : chaque UPDATE porte l'empreinte md5 des variations telles
-- que lues le 2026-09-03. Si un exercice a été modifié depuis, sa ligne n'est
-- PAS mise à jour plutôt que d'écraser le travail du professeur. Le bloc de
-- contrôle final lève un WARNING visible dans la sortie de `db:migrate` si le
-- compte n'est pas celui attendu : un silence ne doit pas passer pour un succès.
--
-- Ces exercices n'existent qu'en production ; la migration est donc un no-op en
-- local (0 ligne touchée, avec le WARNING correspondant), ce qui est normal.
--
-- Contrôle passé avant génération : pour chaque champ, les jetons mathématiques
-- (tildes, dollars, blocs de code, variables, URLs d'images) sont identiques
-- entre français et anglais, aux deux exceptions voulues que sont le texte dans
-- les formules et la virgule décimale. Aucune prose française résiduelle.
-- Les 94 champs ont par ailleurs été relus par Postgres et comparés au md5 près
-- à la source, pour valider l'échappement.

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Find the roots of each of the following polynomials.\n\n1. $x^2+2x-4$\n2. $-x^2-3x+2$"}}'::jsonb, true)
  WHERE id = '2afe76dc-9f94-4570-ba23-dcf01e669357' AND md5(variations::text) = '98cdc36887f3fc7e1bbdd521b0584214';

