UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let ~f~, ~g~ and ~h~ be three functions, defined and differentiable on $\\mathbb{R}$ and never zero on $\\mathbb{R}$. Express the derivatives of the following functions in terms of ~f~, ~g~, ~h~ and their derivatives.\n\nFor example, the derivative of ~fg+h~ is ~f''g+fg''+h''~.\n\nYou may use the fact that\n\n$$(f^n)'' = nf''f^{n-1}.$$\n\n1. ~fg+gh~\n2. ~{f^2}/g~\n3. ~{f^3+g}/{gh}~\n4. ~g-f/{h^3}~\n5. ~f^3g^2~\n6. ~f/{g/h}~\n7. ~sqrt(f/g)~\n8. ~fgh~"}}'::jsonb, true)
  WHERE id = '5f0eb1d7-b142-40af-98a4-41aca81840e8' AND md5(variations::text) = 'd6a7170ae7b55b1b550a88609e44ad4d';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"If ~u~ is a differentiable function taking only strictly positive values, then the function ~sqrt(u)~ is differentiable and\n\n$$(\\sqrt{u})^{\\prime}=\\frac{u''}{2\\sqrt{u}}$$\n\nGive an expression for ~f''(x)~ for each of the following functions ~f~. You are not asked to find the sets on which they are differentiable.\n\n1. ~f(x)=sqrt(3x^2-2x-10)~\n2. ~f(x)=sqrt(2x^3+6x^2-x+3)~\n3. ~f(x)=sqrt({2x+1}/{-3x+9})~\n4. ~f(x)=sqrt({2x^3-x}/{x^5-x^2})~"}}'::jsonb, true)
  WHERE id = '60b0648f-1d34-449b-941f-caf152a6a2a1' AND md5(variations::text) = 'a13ea927fe9b5773d71a413b55fe9da0';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"In each case, decide whether the statement is “true” or “false”, using the completed-square form of a quadratic polynomial.\n\n1. $\\forall x \\in \\mathbb{R}, \\quad x^2 + x + 1 \\geqslant \\frac{1}{2}$\n2. $\\forall t \\in \\mathbb{R}, \\quad t^2 + 3t > -1$\n3. $\\forall z \\in \\mathbb{R}, \\quad 3z + z^2 < 2z^2 - 4$\n4. $\\forall v \\in \\mathbb{R}, \\quad \\frac{4}{49}v^2 + \\frac{61}{9} \\geqslant \\frac{20}{21}v$"}}'::jsonb, true)
  WHERE id = '553b1408-ee55-436f-ae6b-ef7d11ce180d' AND md5(variations::text) = '5387070fbd987f1628118bdac507761e';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let $n \\in \\mathbb{N}^*$. Differentiate the following functions, defined on $\\mathbb{R}$.\n\n*Here, for *$n \\in \\mathbb{N}^*$*, *$n! = 1 \\times 2 \\times 3 \\times \\cdots \\times (n - 1) \\times n$* and *$0! = 1$*.*\n\n1. $f(x) = \\displaystyle\\sum_{k=1}^{n} x^k$\n2. $f(x) = \\displaystyle\\sum_{k=0}^{n} (-1)^{k+1} \\frac{x^k}{k}$\n3. $f(x) = \\displaystyle\\sum_{k=0}^{n} \\frac{x^k}{k!}$\n4. $f(x) = \\displaystyle\\sum_{k=0}^{n} \\frac{(3x)^{2k}}{(2k)!}$"}}'::jsonb, true)
  WHERE id = 'fd4633d9-27b8-40d4-82d5-4bbad5071703' AND md5(variations::text) = '637c344e03e3704bcef1da6a8f7d760c';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"For each graph of a quadratic polynomial, choose the correct completed-square form.\n\n1.\n\n   ![calcul e6sm47db 1](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-e6sm47db-1.png){size=medium align=center}\n\n   1. ~(x+2)^2-1~\n   2. ~(x-2)^2-1~\n   3. ~(x+2)^2+1~\n   4. ~(x-2)^2+1~\n2.\n\n   ![Capture d’écran 2026 01 25 à 10.02.39](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-e6sm47db-2.png){size=medium align=center}\n\n   1. ~-2(x+3)^2-4~\n   2. ~-2(x-3)^2-4~\n   3. ~-2(x+3)^2+4~\n   4. ~-2(x-3)^2+4~"}}'::jsonb, true)
  WHERE id = '730969d2-a464-4a4a-b7aa-08421934a315' AND md5(variations::text) = 'e85fae2d2d0b401c15804698e8e6abee';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let ~f_1~, ~f_2~ and ~f_3~ be functions defined and differentiable on $\\mathbb{R}$.\n\nThe graph of one particular derivative, written ~f''~, is drawn on the axes below. \n\n![Capture d’écran 2026 01 25 à 20.31.55](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/b9kxfw6a-1.png){size=medium align=center}\n\nHere are three variation tables:\n\n![Capture d’écran 2026 01 25 à 20.32.07](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/b9kxfw6a-2.png){size=medium align=center}\n\n~f''~ is the derivative of:\n\n1. ~f_1~\n2. ~f_2~\n3. ~f_3~"}}'::jsonb, true)
  WHERE id = '05fa7419-dc7f-4978-be38-c35800691918' AND md5(variations::text) = 'a16f28d128a4307b1e91c5aa67ab7b6c';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Solve the following inequalities in $\\mathbb{R}$:\n\n1. ~e^x>=1~\n\n2. ~e^{2x}<e~\n\n3. ~(2x-1)e^x>0~\n\n4. ~e^x-e^{-x}<0~\n\n5. ~(e^x-1)(e^{-x}-1)>0~\n\n6. ~2xe^x-6e^x>=0~","solution_md":"1. $e^x \\geqslant 1 \\Longleftrightarrow e^x \\geqslant e^0 \\Longleftrightarrow x \\geqslant 0$    $S = [0~;~+\\infty[$\n2. $e^{2x} < e \\Longleftrightarrow 2x < 1$    $S = \\left]-\\infty~;~\\frac{1}{2}\\right[$\n3. $(2x - 1)e^x > 0 \\Longrightarrow 2x - 1 > 0$ since $\\forall x \\in \\mathbb{R}, e^x > 0$    $S = \\left]\\frac{1}{2}~;~+\\infty\\right[$\n4. $e^x - e^{-x} < 0 \\Longleftrightarrow e^x < e^{-x} \\Longleftrightarrow x < -x$    $S = ]-\\infty~;~0[$\n5. ~(e^x-1)(e^{-x}-1)>0~    \\\n   $S = \\varnothing$\n6. $2xe^x - 6e^x \\geqslant 0 \\Longrightarrow 2x - 6 \\geqslant 0$     $S = [3~;~+\\infty[$"}}'::jsonb, true)
  WHERE id = '34adbec7-6c23-4003-a178-cd15ee3bacc5' AND md5(variations::text) = '80a6d975f3a2640f6fe2e2dc8d5ab9bc';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Consider the function ~f~ defined by ~f(x)=3x^2+4x-2~ for $x \\in \\mathbb{R}$.\n\nAfter working out its completed-square form, decide which of the 3 graphs below is its graph.\n\n1.\n\n   ![Capture d’écran 2026 01 25 à 15.23.17](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-usmurgdr-1.png){size=medium align=center caption=\"Figure 1\"}\n2.\n\n   ![Capture d’écran 2026 01 25 à 15.23.25](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-usmurgdr-2.png){size=medium align=center caption=\"Figure 2\"}\n3.\n\n   ![Capture d’écran 2026 01 25 à 15.23.31](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-usmurgdr-3.png){size=medium align=center caption=\"Figure 3\"}"}}'::jsonb, true)
  WHERE id = 'dd4f11e8-4884-4bf0-936c-dcbc7f745531' AND md5(variations::text) = 'e6ef149a48e83ee7341d107eeacd80a2';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Opposite is the variation table of a function ~f''~ defined on $\\mathbb{R}$ and, below, the graphs of three functions: ~f_1~, ~f_2~ and ~f_3~.\\\n\n\n![Capture d’écran 2026 01 25 à 20.55.51](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-fane3ga6-1.png){size=large align=center}\n\n![Capture d’écran 2026 01 25 à 20.56.02](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-fane3ga6-2.png){size=medium align=center}\n\n![Capture d’écran 2026 01 25 à 20.56.26](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-fane3ga6-3.png){size=medium align=center}\n\n![Capture d’écran 2026 01 25 à 20.56.36](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-fane3ga6-4.png){size=medium align=center}\n\n~f''~ is the derivative of:\n\n1. ~f_1~\n2. ~f_2~\n3. ~f_3~"}}'::jsonb, true)
  WHERE id = '69d2c764-6fe3-4f8f-8097-88787470eac3' AND md5(variations::text) = '8332a54ca2ae9056ec2e7f4be1db61a9';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Below is the variation table of a function ~f''~ defined on $\\mathbb{R}$, together with the graphs of three functions: ~f_1~, ~f_2~ and ~f_3~.\n\n![Capture d’écran 2026 01 25 à 20.44.16](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-xw7a5rf5-1.png){size=large align=center}\n\n![Capture d’écran 2026 01 25 à 20.44.22](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-xw7a5rf5-2.png){size=medium align=center}\n\n![Capture d’écran 2026 01 25 à 20.44.28](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-xw7a5rf5-3.png){size=medium align=center}\n\n![Capture d’écran 2026 01 25 à 20.44.34](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/calcul-xw7a5rf5-4.png){size=medium align=center}\n\nThe function ~f''~ is the derivative of:\n\n1. ~f_1~\n2. ~f_2~\n3. ~f_3~"}}'::jsonb, true)
  WHERE id = 'e9f2323f-d832-42b1-b4bd-ff6ef0aa5ed6' AND md5(variations::text) = '0cc76aa4c94981ce4be09a6651e3e127';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Consider the function ~g~ defined by ~g(t)=-1/2t^2+t-1~ for $t \\in \\mathbb{R}$.\n\nAfter working out its completed-square form, decide which of the 4 graphs below is its graph.\n\n1.\n\n   ![Capture d’écran 2026 01 25 à 15.30.32](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/6mj7h7hh-1.png){size=medium align=center caption=\"Figure 1\"}\n2.\n\n   ![Capture d’écran 2026 01 25 à 15.30.38](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/6mj7h7hh-2.png){size=medium align=center caption=\"Figure 2\"}\n3.\n\n   ![Capture d’écran 2026 01 25 à 15.30.44](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/6mj7h7hh-3.png){size=medium align=center caption=\"Figure 3\"}\n4.\n\n   ![Capture d’écran 2026 01 25 à 15.30.49](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/6mj7h7hh-4.png){size=medium align=center caption=\"Figure 4\"}"}}'::jsonb, true)
  WHERE id = '1f1924bc-5f9a-4636-8d4d-766d767201fa' AND md5(variations::text) = '92c7e8dad44f732fe7d4c05dd3705514';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Simplify the following expressions:\n\n1. ~(e^{2x+1})^3*(e^{-3x})^2~\n2. ~{e^x+e^{-x}}/{e^x}~\n3. ~{e*e^{2x}}/{e^{x+1}}~\n4. ~{e^{4x}}/{(e^x)^2*e}~\n5. ~{e^x+e^{-x}}/{e^{-x}}~\n6. ~e^0*e^{3x}*e^{2-3x}*e~\n7. ~(e^x+e^{-x})^2-(e^x-e^{-x})^2~\n8. ~{e^{2x+3}}/{e^{2x-1}}~\n9. ~(e^x)^5*e^{-2x}~\n10. ~e^{2x}+e^{-2x}-(e^x-e^{-x})^2~\n11. ~sqrt[3](e^4)*(sqrt[3](e))^2~ {{hint:rappel}}\n12. $\\dfrac{e\\sqrt{e}}{e^2\\sqrt[3]{e}}$"}}'::jsonb, true)
  WHERE id = 'eeea0e05-7dfd-41af-9103-34594367a193' AND md5(variations::text) = '10292bc83aa48c0a760bda1e1a3e5453';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Work out the derivative of each function, after finding the interval on which it is differentiable.\n\n1. ~f(x)=e^x-x^2+2~\n2. ~f(x)=(e^x-1)(e^x+1)~\n3. ~f(x)=(x+2)e^x~\n4. ~f(x)=(e^x-x)(e^x+x^2)~\n5. ~f(x)=e^{3x}+e^{-2x}~\n6. ~f(x)={e^x+e^{-x}}/{e^x-e^{-x}}~\n7. ~f(x)={e^x-1}/{e^x+1}~\n8. ~f(x)={xe^{-x}+1}/{x^2+1}~","solution_md":"The first four functions are differentiable on $\\mathbb{R}$.\n\n1. ~f''(x)=e^x-2x~\n2. ~f''(x)=e^x(e^x+1)+(e^x-1)e^x=2e^{2x}~\n3. ~f''(x)=e^x+(x+2)e^x=(x+3)e^x~\n4.\n\n   $$\\begin{align*}f''(x) &= (e^x - 1)(e^x + x^2) + (e^x - x)(e^x + 2x) \\\\\n       &= 2e^{2x} + (x^2 + x - 1)e^x - 3x^2\\end{align*}$$\n5. ~f~ is differentiable on $\\mathbb{R}$ and ~f''(x)=3e^{3x}-2e^{-2x}~.\n6. ~f~ is differentiable on $]-\\infty~;~0[$ and on $]0~;~+\\infty[$,\n\n   ~~f''(x)={(e^x-e^{-x})^2-(e^x+e^{-x})^2}/{(e^x-e^{-x})^2}={-4}/{(e^x-e^{-x})^2}~~\n7. ~f~ is differentiable on $\\mathbb{R}$\n\n   ~~f''(x)={e^x(e^x+1)-e^x(e^x-1)}/{(e^x+1)^2}={2e^x}/{(e^x+1)^2}~~\n8. ~f~ is differentiable on $\\mathbb{R}$\n\n   $$\\begin{align*}f''(x) &= \\frac{(e^{-x} - xe^{-x})(x^2 + 1) - 2x(xe^{-x} + 1)}{(x^2 + 1)^2} \\\\\n       &= \\frac{(-x^3 - x^2 - x + 1)e^{-x} - 2x}{(x^2 + 1)^2}\\end{align*}$$"}}'::jsonb, true)
  WHERE id = '5ba72e43-2fd8-4075-b80d-d99325ed86f2' AND md5(variations::text) = 'bf6d8e013c24526cf5cb5b0c519f23fc';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let ~(u_n)~ be an arithmetic sequence with first term ~u_0~ and non-zero common difference ~r~. For every natural number ~n~, set ~v_n=e^{-u_n}~.\n\n1. What kind of sequence is ~(v_n)~?\n2. Show that for every natural number ~n~,\n\n   $$s_{n}=v_0+v_1+\\cdots+v_{n}=v_{n}\\frac{e^{(n+1)r} - 1}{e^r - 1}$$","solution_md":"1. Since ~(u_n)~ is arithmetic with first term ~u_0~ and common difference ~r!=0~, for every natural number ~n~ we have:\n\n   $$v_{n}=e^{-(u_0+nr)}=e^{-u_0}e^{-nr}$$\n\n   which gives\n\n   ~~v_{n+1}=e^{-u_0}e^{-(n+1)r}=e^{-r}*e^{-u_0}e^{-nr}=e^{-r}v_n~~\n\n   We conclude that the sequence ~(v_n)~ is geometric with first term ~v_0=e^{-u_0}~ and common ratio ~q=e^{-r}~.\n2. As ~r!=0~, we have ~q=e^{-r}!=1~. For every integer ~n>=0~, ~s_n~ is the sum of the first ~n+1~ terms of the geometric sequence ~(v_n)~.\n\n   Hence: \n   \n   $$\\begin{align*}s_{n} & =v_0\\frac{1 - q^{n+1}}{1 - q}\\\\  & =e^{-u_0}\\frac{1 - e^{-r(n+1)}}{1 - e^{-r}}\\\\  & =e^{-u_0}\\frac{1 - \\frac{1}{e^{(n+1)r}}}{1 - \\frac{1}{e^r}}\\\\  & =e^{-u_0}\\frac{e^{(n+1)r} - 1}{e^{(n+1)r}}\\times\\frac{e^r}{e^r - 1}\\\\  & =e^{-(u_0+nr)}\\times\\frac{e^{(n+1)r} - 1}{e^r - 1}\\\\  & =v_{n}\\frac{e^{(n+1)r} - 1}{e^r - 1}\\end{align*}$$"}}'::jsonb, true)
  WHERE id = 'cd9e0bc7-6be8-4d12-9659-a681f563e162' AND md5(variations::text) = 'af83f2a93dad7dcc7cdd2d0778b0dc96';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Two zip lines are to be built from a vertical post $[BH]$, as shown in the diagram below, where ~AC=200~ m, ~AB=150~ m and $\\widehat{A} = 32°$.  \n\n![Une tyrolienne](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/geometrie-mapyv8pa-1.webp){size=medium align=center}\n\nHow long is the zip line represented by the segment $[BC]$? What is the size of the angle $\\widehat{C}$?","solution_md":"By the cosine rule:\n\n$$\\begin{align*}BC^2 &= AB^2 + AC^2 - 2 \\times AB \\times AC \\times \\cos(\\widehat{BAC}) \\\\\n\\Leftrightarrow BC^2 &= 150^2 + 200^2 - 2 \\times 150 \\times 200 \\times \\cos(32°) \\\\\n\\Leftrightarrow BC^2 &= 62\\,500 - 60\\,000 \\times \\cos(32°).\\end{align*}$$\n\n~BC~ is a positive quantity, so:\n\n$$BC = \\sqrt{62\\,500 - 60\\,000 \\times \\cos(32°)} \\approx 107.78.$$\n\nThe zip line represented by the segment $[BC]$ is $107.78$ m long, to the nearest centimetre.\n\nBy the cosine rule:\n\n$$\\begin{align*}AB^2 &= AC^2 + BC^2 - 2 \\times AC \\times BC \\times \\cos(\\hat{C}) \\\\\n\\Leftrightarrow \\cos(\\hat{C}) &= \\dfrac{AC^2 + BC^2 - AB^2}{2 \\times AC \\times BC} \\\\\n\\Leftrightarrow \\cos(\\hat{C}) &= \\dfrac{200^2 + 107.78^2 - 150^2}{2 \\times 200 \\times 107.78}.\\end{align*}$$\n\nA calculator gives the angle to the nearest $0.1°$, namely $\\hat{C} \\approx 47.5°$."}}'::jsonb, true)
  WHERE id = 'd32464db-2907-431a-85f3-acda2698ebe0' AND md5(variations::text) = '341a7b57fbbe77cf8ee6ed9c225f3ab0';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Solve the following equations in $\\mathbb{R}$:\n\n1. ~e^x=-2~\n2. ~e^{2x}=e~\n3. ~e^{x^2}=e^9~\n4. ~e^x-1=0~\n5. ~e^x=e^{-x}~\n6. ~e^{-x}=e^3~\n7. ~e^{x^2+3x+1}=e^3~\n8. ~e^{5x}=e^{-3x}~\n9. ~e^{x^2+12x+35}=1~\n10. ~(e^x-1)(e^x-e^5)=0~\n11. ~(e^x+8)(e^{-x^2+4}-e^{3x})=0~\n12. ~2xe^x-6e^x=0~","solution_md":"1. ~e^x=-2~ is impossible, since ~e^x>0~ for every real ~x~    so $S = \\varnothing$\n2. $e^{2x} = e \\Longleftrightarrow 2x = 1$,     $S = \\left\\{\\frac{1}{2}\\right\\}$\n3. $e^{x^2} = e^9 \\Longleftrightarrow x^2 = 9$,     $S = \\{-3~;~3\\}$\n4. $e^x - 1 = 0 \\Longleftrightarrow e^x = e^0$,     $S = \\{0\\}$\n5. $e^x = e^{-x} \\Longleftrightarrow x = -x$,     $S = \\{0\\}$\n6. $e^{-x} = e^3 \\Longleftrightarrow -x = 3$,     $S = \\{-3\\}$\n7. $e^{x^2+3x+1} = e^3 \\Longleftrightarrow x^2 + 3x + 1 = 3$    $S = \\left\\{\\frac{-3 - \\sqrt{17}}{2}~;~\\frac{-3 + \\sqrt{17}}{2}\\right\\}$.\n8. $e^{5x} = e^{-3x} \\Longleftrightarrow 5x = -3x$     $S = \\{0\\}$.\n9. $e^{x^2+12x+35} = 1 \\Longleftrightarrow x^2 + 12x + 35 = 0$    $S = \\{-7~;~-5\\}$.\n10. $(e^{x}-1)(e^{x}-e^5)=0\\Longleftrightarrow e^{x}=e^0\\text{ or }e^{x}=e^5$    $S = \\{0~;~5\\}$.\n11. ~(e^x+8)(e^{-x^2+4}-e^{3x})=0~    $\\Longleftrightarrow e^{x}=-8\\text{ or }e^{-x^2+4}=e^{3x}$\\\n   The first equation has no solution. The second has two solutions.    $S = \\{-4~;~1\\}$.\n12. $2xe^{x}-6e^{x}=0\\Longleftrightarrow2x-6=0\\text{ or }e^{x}=0$ \\\n   The first equation has one solution. The second has none.    $S = \\{3\\}$"}}'::jsonb, true)
  WHERE id = '36339309-7225-4be7-9be1-d18a6fbab57f' AND md5(variations::text) = '6298563bc590b7ee74764a810bd04e3f';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let sinh and cosh denote the functions defined for every real ~x~ by: $\\sinh(x) = \\frac{e^x - e^{-x}}{2} \\quad \\text{and} \\quad \\cosh(x) = \\frac{e^x + e^{-x}}{2}.$\n\n1. **Studying the function sinh**\n   1. Show that the function sinh is odd.\n   2. Work out the derivative of sinh and give its sign.\n   3. Draw up the variation table of the function sinh on $[0~;~+\\infty[$.\n   4. Draw up a table of values.\n   5. On orthogonal axes, sketch the graph of the function sinh on $[0~;~+\\infty[$. Complete it using a symmetry, which you should state, to obtain the curve $\\mathcal{C}_1$ representing sinh on $\\mathbb{R}$.\n   6. Determine the sign of ~sinh(x)~ according to the values of ~x~.\n2. **Studying the function cosh**\n   1. Show that the function cosh is even.\n   2. Work out the derivative of cosh and give its sign.\n   3. Draw up the variation table of the function cosh on $[0~;~+\\infty[$.\n   4. Draw up a table of values.\n   5. On orthogonal axes, sketch the graph of the function cosh on $[0~;~+\\infty[$. Complete it using a symmetry, which you should state, to obtain the curve $\\mathcal{C}_2$ representing cosh on $\\mathbb{R}$.\n3. **Relative position of $\\mathcal{C}_1$ and $\\mathcal{C}_2$**\n   1. Show that for every real ~x~, ~cosh(x)-sinh(x)=e^{-x}~.\n   2. Show that for every real ~x~, ~cosh(x)>sinh(x)~.\n   3. Hence deduce the relative position of the curves $\\mathcal{C}_1$ and $\\mathcal{C}_2$."}}'::jsonb, true)
  WHERE id = '9d38f891-96ff-4938-b07a-9dbc21bd3125' AND md5(variations::text) = '4e399249652426854939bc419b97abcf';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Consider the point $A(3\\,;0)$ and the line ~d~ with equation ~3x-2y+4=0~. Let ~H~ be the foot of the perpendicular from the point ~A~ to the line ~d~.\n\n1. Let ~h~ be the x-coordinate of the point ~H~. Write the y-coordinate of ~H~ in terms of ~h~.\n\n2. Find the value of ~h~ using a scalar product.\n3. What are the coordinates of ~H~?\n4. Hence deduce the distance from the point ~A~ to the line ~d~, given by the length ~AH~.","solution_md":"1. As the point ~H~ lies on the line ~d~, we know that ~3x_H-2y_H+4=0~, so\n\n   ~~y_H={3x_H+4}/2={{3h+4}/2}.~~\n2. ~H~ is the foot of the perpendicular from the point ~A~ to the line ~d~, which means the vector $\\overrightarrow{AH}$ is perpendicular to every direction vector of the line ~d~.    Let $\\vec{u}$ be a direction vector of ~d~: then $\\vec{u}\\begin{pmatrix} 2 \\\\ 3 \\end{pmatrix}$ and $\\overrightarrow{AH}\\begin{pmatrix} h - 3 \\\\ y_H \\end{pmatrix}$. Hence:\n\n   $$\\begin{align*}\\overrightarrow{AH} \\cdot \\vec{u} &= 2(h - 3) + 3 \\times \\dfrac{3h + 4}{2} \\\\\n       &= 2h - 6 + \\dfrac{9h + 12}{2} \\\\\n       &= 2h - 6 + \\dfrac{9h}{2} + 6 = \\dfrac{13h}{2}.\\end{align*}$$\n\n   This scalar product is zero, so solving the equation ~{13h}/2=0~ gives ~h=0~.\n3. Therefore ~y_H={3x_H+4}/2=4/2=2~, so the coordinates of ~H~ are $(0\\,;2)$.\n4. Since ~H~ is the foot of the perpendicular from ~A~ to ~d~, the distance from ~A~ to ~d~ is given by the length ~AH~. We have:\n\n   $$\\begin{align}\n   AH^2 &= (x_H - x_A)^2 + (y_H - y_A)^2 \\\\\n   &= (0 - 3)^2 + (2 - 0)^2 \\\\\n   &= 9 + 4\\\\\n   &= 13\n   \\end{align}$$\n\n   so ~AH=sqrt(13)~."}}'::jsonb, true)
  WHERE id = '96c54dc9-830f-4aa7-90f3-4d58acb18f1d' AND md5(variations::text) = '442723718508f42ad84355e44ec5b7ef';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let ~A~ and ~B~ be two points in the plane with ~AB=6~, let ~I~ be the midpoint of $[AB]$ and let ~M~ be a point in the plane.\n\n1.\n   1. Justify that $\\overrightarrow{MA} = \\overrightarrow{MI} + \\overrightarrow{IA}$ and $\\overrightarrow{MB} = \\overrightarrow{MI} + \\overrightarrow{IB}$.\n   2. Hence deduce that ~MA^2+MB^2=2MI^2+{AB^2}/2~.\n\n   This identity is known as the second median theorem.\n2.\n   1. Prove the equivalence ~MA^2+MB^2=20<=>MI^2=1~.\n   2. Hence describe the set of points ~M~ such that ~MA^2+MB^2=20~.","solution_md":"1.\n   1. By Chasles'' relation, we have:\n\n      $$\\overrightarrow{MA} = \\overrightarrow{MI} + \\overrightarrow{IA} \\text{ and } \\overrightarrow{MB} = \\overrightarrow{MI} + \\overrightarrow{IB}.$$\n   2.\n\n      $$\\begin{align*}MA^2 + MB^2 &= \\left(\\overrightarrow{MI} + \\overrightarrow{IA}\\right)^2 + \\left(\\overrightarrow{MI} + \\overrightarrow{IB}\\right)^2 \\\\\n             &= MI^2 + 2\\overrightarrow{MI} \\cdot \\overrightarrow{IA} + IA^2 + MI^2 + 2\\overrightarrow{MI} \\cdot \\overrightarrow{IB} + IB^2 \\\\\n             &= 2MI^2 + 2\\overrightarrow{MI} \\cdot \\left(\\overrightarrow{IA} + \\overrightarrow{IB}\\right) + 2\\left(\\dfrac{AB}{2}\\right)^2 \\\\\n             &= 2MI^2 + \\dfrac{AB^2}{2}.\\end{align*}$$\n2.\n   1.\n\n      $$\\begin{align*}MA^2 + MB^2 = 20 &\\Leftrightarrow 2MI^2 + \\dfrac{AB^2}{2} = 20 \\\\\n             &\\Leftrightarrow 2MI^2 + \\dfrac{6^2}{2} = 20 \\\\\n             &\\Leftrightarrow 2MI^2 = 2 \\\\\n             &\\Leftrightarrow MI^2 = 1.\\end{align*}$$\n   2. ~MI~ is a positive quantity, so ~MI=1~, and the set of points ~M~ such that ~MA^2+MB^2=20~ is the circle with centre ~I~ and radius ~1~."}}'::jsonb, true)
  WHERE id = '98e57f6c-2d96-43f1-8f85-0f5d7bf0c6f7' AND md5(variations::text) = '7199c546c8638dbe089a47800e54b604';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Find any values of the real number ~t~ for which the vectors $\\vec{u}$ and $\\vec{v}$ are perpendicular.\n\n1. $\\vec{u}\\begin{pmatrix} -2 \\\\ t \\end{pmatrix}$ and $\\vec{v}\\begin{pmatrix} 4t \\\\ 2 \\end{pmatrix}$\n\n2. $\\vec{u}\\begin{pmatrix} t \\\\ -2 \\end{pmatrix}$ and $\\vec{v}\\begin{pmatrix} t+6 \\\\ 2t - \\dfrac{1}{2} \\end{pmatrix}$\n3. $\\vec{u}\\begin{pmatrix} \\sqrt{3}\\,t \\\\ 2t \\end{pmatrix}$ and $\\vec{v}\\begin{pmatrix} \\sqrt{5}\\,t + 1 \\\\ \\sqrt{12} \\end{pmatrix}$","solution_md":"1. $\\vec{u} \\cdot \\vec{v} = -8t + 2t = -6t$. The vectors are perpendicular if and only if their scalar product is zero, which means ~-6t=0~. The vectors are perpendicular when ~t=0~.\n2.\n\n   $$\\begin{align*}\n   \\vec{u} \\cdot \\vec{v} &= t(t + 6) - 2\\left(2t - \\dfrac{1}{2}\\right) \\\\\n   &= t^2 + 6t - 4t + 1 \\\\\n   &= t^2 + 2t + 1 \\\\\n   &= (t + 1)^2\n   \\end{align*}$$\n\n   The vectors are perpendicular if and only if their scalar product is zero, which means ~(t+1)^2=0~, so ~t+1=0~, so ~t=-1~. The vectors are perpendicular when ~t=-1~.\n3.\n\n   $$\\begin{align*}\\vec{u} \\cdot \\vec{v} &= \\sqrt{3}\\,t \\times (\\sqrt{5}\\,t + 1) + 2t \\times \\sqrt{12} \\\\\n       &= \\sqrt{15}\\,t^2 + \\sqrt{3}\\,t + 2\\sqrt{12}\\,t \\\\\n       &= \\sqrt{15}\\,t^2 + (\\sqrt{3} + 4\\sqrt{3})t \\\\\n       &= \\sqrt{15}\\,t^2 + 5\\sqrt{3}\\,t \\\\\n       &= \\sqrt{15}(t^2 + \\sqrt{5}\\,t) \\\\\n       &= \\sqrt{15}\\,t(t + \\sqrt{5}).\\end{align*}$$\n\n   The vectors are perpendicular if and only if their scalar product is zero, which means ~t(t+sqrt(5))=0~, so the solutions of this null-product equation are ~0~ and ~-sqrt(5)~.    The vectors are perpendicular for two values of ~t~: ~0~ and ~-sqrt(5)~."}}'::jsonb, true)
  WHERE id = '36188a42-cda5-45aa-9c2a-936ce59e5073' AND md5(variations::text) = '40606e2e374f3d1ddd83af5606660d4f';

UPDATE public.exercises SET variations = jsonb_set(jsonb_set(jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let $a$ and $b$ be two real numbers.\n\n1. Write out the expansion of $(x-y)^2$.\n2. Simplify the expression $\\left(e^{\\frac{a}{2}}\\right)^2$.\n3. Using the two previous questions, write  $e^{a}+e^{b}-2e^{\\frac{a+b}{2}}$in the form $\\left(x-y\\right)^2$.\n4. Study the sign of $\\frac{e^{a}+e^{b}}{2}-e^{\\frac{a+b}{2}}$.\n5. Compare $e^{\\frac{a+b}{2}}$and $\\frac{e^{a}+e^{b}}{2}$.\n6. Interpret this result graphically.","solution_md":"For all real numbers ~a~ and ~b~, we have:\n\n$$\\begin{align*}\\frac{e^a + e^b}{2}-e^{\\frac{a+b}{2}} & =\\frac{e^a + e^b - 2e^{\\frac{a+b}{2}}}{2}\\\\  & =\\frac{(e^{\\frac{a}{2}})^2 + (e^{\\frac{b}{2}})^2 - 2e^{\\frac{a}{2}} \\times e^{\\frac{b}{2}}}{2}\\\\  & =\\frac{(e^{\\frac{a}{2}} - e^{\\frac{b}{2}})^2}{2}\\geqslant0\\end{align*}$$\n\nWe conclude that, whatever the real numbers ~a~ and ~b~, the inequality ~{e^a+e^b}/2>=e^{{a+b}/2}~ holds"}}'::jsonb, true), '{1,translations}', '{"en":{"statement_md":"Let $a$ and $b$ be two real numbers. \n\n1. Study the sign of $\\frac{e^{a}+e^{b}}{2}-e^{\\frac{a+b}{2}}$.\n2. Compare $e^{\\frac{a+b}{2}}$and $\\frac{e^{a}+e^{b}}{2}$.\n3. Interpret this result graphically","solution_md":"For all real numbers ~a~ and ~b~, we have:\n\n$$\\begin{align*}\\frac{e^a + e^b}{2}-e^{\\frac{a+b}{2}} & =\\frac{e^a + e^b - 2e^{\\frac{a+b}{2}}}{2}\\\\  & =\\frac{(e^{\\frac{a}{2}})^2 + (e^{\\frac{b}{2}})^2 - 2e^{\\frac{a}{2}} \\times e^{\\frac{b}{2}}}{2}\\\\  & =\\frac{(e^{\\frac{a}{2}} - e^{\\frac{b}{2}})^2}{2}\\geqslant0\\end{align*}$$\n\nWe conclude that, whatever the real numbers ~a~ and ~b~, the inequality ~{\\euler^a+\\euler^b}/2>=\\euler^{{a+b}/2}~ holds"}}'::jsonb, true), '{2,translations}', '{"en":{"statement_md":"Let $a$ and $b$ be two real numbers. \n\n1. Compare $e^{\\frac{a+b}{2}}$and $\\frac{e^{a}+e^{b}}{2}$.\n2. Interpret this result graphically","solution_md":"For all real numbers ~a~ and ~b~, we have:\n\n$$\\begin{align*}\\frac{e^a + e^b}{2}-e^{\\frac{a+b}{2}} & =\\frac{e^a + e^b - 2e^{\\frac{a+b}{2}}}{2}\\\\  & =\\frac{(e^{\\frac{a}{2}})^2 + (e^{\\frac{b}{2}})^2 - 2e^{\\frac{a}{2}} \\times e^{\\frac{b}{2}}}{2}\\\\  & =\\frac{(e^{\\frac{a}{2}} - e^{\\frac{b}{2}})^2}{2}\\geqslant0\\end{align*}$$\n\nWe conclude that, whatever the real numbers ~a~ and ~b~, the inequality ~{\\euler^a+\\euler^b}/2>=\\euler^{{a+b}/2}~ holds"}}'::jsonb, true)
  WHERE id = '47730c10-fad8-4b5e-956c-f1ddb54f496e' AND md5(variations::text) = 'c7a994d3c532cfcd98774681305ca4a4';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Consider the following points in the plane: $A(-10\\,;4)$, $B(-4\\,;1)$ and $C(-1\\,;7)$.\n\n1. Using the scalar product, show that the triangle ~ABC~ is right-angled.\n\n2. Find the coordinates of the point ~D~ such that the quadrilateral ~ABCD~ is a rectangle.","solution_md":"1. Work out the components of the vectors $\\overrightarrow{AB}$, $\\overrightarrow{BC}$ and $\\overrightarrow{CA}$:\n\n   $$\\overrightarrow{AB}\\begin{pmatrix}-4-(-10)\\\\ 1-4\\end{pmatrix},\\text{ so }\\overrightarrow{AB}\\begin{pmatrix}6\\\\ -3\\end{pmatrix}$$\n\n   $$\\overrightarrow{BC}\\begin{pmatrix}-1-(-4)\\\\ 7-1\\end{pmatrix},\\text{ so }\\overrightarrow{BC}\\begin{pmatrix}3\\\\ 6\\end{pmatrix}$$\n\n   $$\\overrightarrow{CA}\\begin{pmatrix}-10-(-1)\\\\ 4-7\\end{pmatrix},\\text{ so }\\overrightarrow{CA}\\begin{pmatrix}-9\\\\ -3\\end{pmatrix}$$\n\n   Work out the three scalar products of the sides of the triangle:\n\n   $$\\overrightarrow{AB}\\cdot\\overrightarrow{BC}=6\\times3+(-3)\\times6=0$$\n\n   $$\\overrightarrow{BC}\\cdot\\overrightarrow{CA}=3\\times(-9)+6\\times(-3)=-27-18=-45$$\n\n   $$\\overrightarrow{CA}\\cdot\\overrightarrow{AB}=(-9)\\times6+(-3)\\times(-3)=-54+9=-45$$\n\n   We deduce that the triangle ~ABC~ is right-angled at ~B~.\n2. **Method 1:**The diagonals of the rectangle ~ABCD~ are $[AC]$ and $[BD]$. As a rectangle is a parallelogram, the diagonals share the same midpoint ~O~, with coordinates:\n\n   $$O\\left(\\dfrac{x_A + x_C}{2}\\,;\\dfrac{y_A + y_C}{2}\\right)$$\n\n   $$O\\left(\\dfrac{-10 + (-1)}{2}\\,;\\dfrac{4 + 7}{2}\\right)$$\n\n   $$O\\left(-\\dfrac{11}{2}\\,;\\dfrac{11}{2}\\right)$$\n\n   But we also know that\n\n   $$O\\left(\\dfrac{x_B + x_D}{2}\\,;\\dfrac{y_B + y_D}{2}\\right)$$\n\n   $$O\\left(\\dfrac{-4 + x_D}{2}\\,;\\dfrac{1 + y_D}{2}\\right).$$\n\n   So ~{-4+x_D}/2=-11/2~ and ~{1+y_D}/2=11/2~, hence ~x_D=-7~ and ~y_D=10~.    The coordinates of the point ~D~ such that the quadrilateral ~ABCD~ is a rectangle are therefore $D(-7\\,;10)$.\\\n\n\n   **Method 2:**\n\n   As ~ABCD~ is a parallelogram, $\\overrightarrow{AB} = \\overrightarrow{DC}$, and $\\overrightarrow{AB}\\begin{pmatrix} 6 \\\\ -3 \\end{pmatrix}$, so $\\overrightarrow{DC}\\begin{pmatrix} 6 \\\\ -3 \\end{pmatrix}$.\n\n   Since $x_{\\overrightarrow{DC}} = x_C - x_D = -1 - x_D$ and $y_{\\overrightarrow{DC}} = y_C - y_D = 7 - y_D$, we deduce that ~x_D=-1-6=-7~ and ~y_D=7-(-3)=10~. The coordinates of the point ~D~ such that the quadrilateral ~ABCD~ is a rectangle are therefore $D(-7\\,;10)$."}}'::jsonb, true)
  WHERE id = '8547cfc8-d070-4fd1-9d87-7ec23a31ee1a' AND md5(variations::text) = 'd56f44bfb68d53e64f4f0247af1366fd';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"1. Show that for every real ~x~, ~1+x<=e^x~.\n2. For every natural number ~n>=2~, deduce the double inequality\n\n   $$\\left(1+\\frac{1}{n}\\right)^{n}\\leqslant e\\leqslant\\left(1-\\frac{1}{n}\\right)^{-n}$$\n3. Give an algorithm that returns an approximation of ~e~ to within ~10^{-P}~, where the integer ~P~ is chosen by the user.\n4. Implement this algorithm in Python and give an approximation of $e$ to $5$decimal places.","solution_md":"1. For every real ~x~, let ~f(x)=e^x-(1+x)~.    The function ~f~ is differentiable on $\\mathbb{R}$ as a difference, and  ~f''(x)=e^x-1.~    We deduce\n\n   $$f^{\\prime}(x)=0\\Leftrightarrow x=0$$\n\n   which gives the following variation table.\n\n   \\begin{tabular}{|c|ccc|}\n\n   ```variation\n   variable: x\n   domain: -inf, 0, +inf\n   \n   sign: f''(x)\n     -inf,0: -\n     0: z\n     0,+inf: +\n   \n   variation: f(x)\n     -inf: , top\n     0: 0, bottom\n     +inf: , top\n   ```\n\n   It follows that the function ~f~ reaches a minimum ~f(0)=0~ at ~x=0~. For every real ~x~, we conclude:\n\n   $$f(x)\\geqslant0,\\text{ that is }1+x\\leqslant e^{x}.$$\n2.\n   - In particular, for ~x=1/n~ with ~n>=2~, we get\n\n     ~~0<1+1/n<=e^{1/n}.~~\n\n     Since the function $x \\mapsto x^n$ is increasing on $\\mathbb{R}^+$, we deduce\n\n     $$\\left(1+\\frac{1}{n}\\right)^{n}\\leq(e^{\\frac{1}{n}})^{n},\\text{ that is }\\left(1+\\frac{1}{n}\\right)^{n}\\leq e$$\n   - In particular, for ~x=-1/n~ with ~n>=2~, we get  ~0<=1-1/n<=e^{-1/n}.~    In the same way, using that $x \\mapsto x^n$ is increasing on $\\mathbb{R}^+$, we obtain\n\n     $$\\left(1 - \\frac{1}{n}\\right)^n \\leq (e^{-\\frac{1}{n}})^n, \\text{ that is } 0 < \\left(1 - \\frac{1}{n}\\right)^n \\leq e^{-1}.$$\n\n     Using that $x \\mapsto \\dfrac{1}{x}$ is decreasing on $]0, +\\infty[$, we get\n\n     ~~(1-1/n)^{-n}>=e.~~\n\n     For every natural number ~n>=2~, we conclude\n\n     ~~(1+1/n)^n<=e<=(1-1/n)^{-n}~~\n3. Noting that the double inequality from question 2 is equivalent to\n\n   $$0 \\leq e - \\left(1 + \\frac{1}{n}\\right)^n \\leq \\left(1 - \\frac{1}{n}\\right)^{-n} - \\left(1 + \\frac{1}{n}\\right)^n,$$\n\n   we obtain the required algorithm.\n\n   $U \\leftarrow 2.25$\\\n   $N \\leftarrow 2$\\\n   While $(1 - \\frac{1}{N})^{-N} - U \\geq 10^{-P}$\\\n   $\\quad U \\leftarrow (1 + \\frac{1}{N})^N$\\\n   $\\quad N \\leftarrow N + 1$ \\\\\n   End While\n\n   ```python\n   p=int(input(\"p=\"))\n   u=2.25\n   n=2\n   while (1-1/n)**(-n)-u>=10**(-p):\n      u=(1+1/n)**n\n      n=n+1\n   print(n)\n   print(u)  \n   ```"}}'::jsonb, true)
  WHERE id = '94ab6221-799a-4099-a5c7-66e4a600ac80' AND md5(variations::text) = 'ece5b7721815608cf23d0ce412c26440';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"In $2020$, a town had $10000$ inhabitants.\n\nThe change in the town''s population is modelled by the sequence ~(u_n)~ defined by: \n\n$$\\begin{cases}u_0 & =10000\\\\ u_{n+1} & =1.08u_{n}-300,\\quad n\\in\\mathbb{N}\\end{cases}$$\n\nwhere ~u_n~ is the number of inhabitants in the year ~2020+n~.\n\n1. State what ~u_1~ represents and work out its value.\n2. Consider the sequence ~(v_n)~ defined for every natural number ~n~ by ~v_n=u_n-3750~.\n   1. Find ~v_0~.\n   2. Prove that for every natural number ~n~, $v_{n+1}=1.08v_{n}$.\n   3. Hence state what kind of sequence ~(v_n)~ is.\n   4. For every natural number ~n~, express ~v_n~ in terms of ~n~.\n   5. Hence deduce that for every natural number,\n\n      $$u_n = 6250 \\times 1.08^n + 3750.$$\n3. The table opposite, taken from a spreadsheet, was obtained by filling down after entering the following formula in cell B2:    `= 62501.08^A2 + 3750` . \n\n   The council is considering opening a new nursery school as soon as the population reaches $19000$ inhabitants.    As such a building takes two years to construct, find the year in which construction must begin.\n\n   **Help with the calculations:**    ~10000-3750=6250~ ;    $1.08\\times4050=4374$ ;    $\\dfrac{4050}{1.08}=3750$ ;    $3750\\times1.08=4050$\n\n   :table-cross\n   |  | A | B |\n   |:---:|:---:|:---:|\n   | $1$ | $n$ | $u_n$ |\n   | $2$ | $0$ | $10000$ |\n   | $3$ | $1$ | $10500$ |\n   | $4$ | $2$ | $11040$ |\n   | $5$ | $3$ | $11623.2$ |\n   | $6$ | $4$ | $12253.056$ |\n   | $7$ | $5$ | $12933.30048$ |\n   | $8$ | $6$ | $13667.96456$ |\n   | $9$ | $7$ | $14461.40168$ |\n   | $10$ | $8$ | $15318.31381$ |\n   | $11$ | $9$ | $16243.77892$ |\n   | $12$ | $10$ | $17243.28123$ |\n   | $13$ | $11$ | $18322.74373$ |\n   | $14$ | $12$ | $19488.56323$ |\n   | $15$ | $13$ | $20747.64829$ |\n   | $16$ | $14$ | $22107.46015$ |\n   | $17$ | $15$ | $23576.05696$ |\n   | $18$ | $16$ | $25162.14152$ |\n   | $19$ | $17$ | $26875.11284$ |\n   | $20$ | $18$ | $28725.12187$ |\n   | $21$ | $19$ | $30723.13162$ |"}}'::jsonb, true)
  WHERE id = 'ad62872f-3dbe-4544-a079-12bf94ba171e' AND md5(variations::text) = 'dc4cb0eadfe775da38e978d2cfe0f50f';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"In a given unit of length, consider a square ~ABCD~ of side ~3~, with two identical rectangles ~BEFC~ and ~EGHF~ of width ~2~ attached to it.\\\n\n\n![Capture d’écran 2026 04 22 à 10.52.58](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/geometrie-sap4d8ak-1.webp){size=medium align=center}\n\nUsing the projection formula, work out the following scalar products.\n\n1. $\\overrightarrow{AB} \\cdot \\overrightarrow{AC}$\n2. $\\overrightarrow{BA} \\cdot \\overrightarrow{BF}$\n3. $\\overrightarrow{EI} \\cdot \\overrightarrow{AG}$\n4. $\\overrightarrow{CF} \\cdot \\overrightarrow{GD}$\n5. $\\overrightarrow{IC} \\cdot \\overrightarrow{HG}$\n6. $\\overrightarrow{EJ} \\cdot \\overrightarrow{FA}$","solution_md":"1. Project the vector $\\overrightarrow{AC}$ onto the vector $\\overrightarrow{AB}$:\n\n   $$\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=\\overrightarrow{AB}\\cdot\\overrightarrow{AB}=3\\times3=9$$\n2. Project the vector $\\overrightarrow{BF}$ onto the vector $\\overrightarrow{BE}$:\n\n   $$\\overrightarrow{BA}\\cdot\\overrightarrow{BF}=\\overrightarrow{BA}\\cdot\\overrightarrow{BE}=-3\\times2=-6$$\n3. Project the vector $\\overrightarrow{EI}$ onto the vector $\\overrightarrow{EB}$:\n\n   $$\\overrightarrow{EI}\\cdot\\overrightarrow{AG}=\\overrightarrow{EB}\\cdot\\overrightarrow{AG}=-2\\times7=-14$$\n4. Project the vector $\\overrightarrow{GD}$ onto the vector $\\overrightarrow{HD}$:\n\n   $$\\overrightarrow{CF}\\cdot\\overrightarrow{GD}=\\overrightarrow{CF}\\cdot\\overrightarrow{HD}=-2\\times7=-14$$\n5. The lines ~(BC)~ and ~(GH)~ are parallel, so project the vector $\\overrightarrow{IC}$ onto the vector $\\overrightarrow{HG}$.    To work out the length ~IC~, use the intercept theorem in the triangle ~GHD~:\n\n   $$\\dfrac{IC}{GH}=\\dfrac{DC}{DH},\\text{ so }IC=\\dfrac{DC \\times GH}{DH}=\\dfrac{3 \\times3}{7}=\\dfrac{9}{7}$$\n\n   Then\n\n   $$\\overrightarrow{IC}\\cdot\\overrightarrow{HG}=-\\dfrac{9}{7}\\times3=-\\dfrac{27}{7}$$\n6. To work out the length ~EJ~, use the intercept theorem in the triangle ~AGD~:\n\n   $$\\dfrac{EJ}{AD}=\\dfrac{GE}{GA},\\text{ so }EJ=\\dfrac{GE \\times AD}{GA}=\\dfrac{2 \\times3}{7}=\\dfrac{6}{7}$$\n\n   Project the vector $\\overrightarrow{FA}$ onto the vector $\\overrightarrow{FE}$:\n\n   $$\\overrightarrow{EJ}\\cdot\\overrightarrow{FA}=\\overrightarrow{EJ}\\cdot\\overrightarrow{FE}=-\\dfrac{6}{7}\\times3=-\\dfrac{18}{7}$$"}}'::jsonb, true)
  WHERE id = '67743200-00ae-4ade-a7fc-9e2348d6837b' AND md5(variations::text) = '2cabe516fd6cc4ee7c7b7cbb331561cb';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Consider the points $A(5\\,;-3)$, $B(-2\\,;7)$, $C\\left(\\dfrac{-1}{2}\\,;0\\right)$ and $D\\left(-5\\,;\\dfrac{3}{4}\\right)$. Work out the following scalar products. \n\n1. $\\overrightarrow{AB} \\cdot \\overrightarrow{CD}$\n\n2. $\\overrightarrow{AC} \\cdot \\overrightarrow{BD}$\n3. $\\overrightarrow{AD} \\cdot \\overrightarrow{BC}$","solution_md":"1. Work out the components of the vectors $\\overrightarrow{AB}$ and $\\overrightarrow{CD}$:\n\n   $$\\overrightarrow{AB}\\begin{pmatrix} -2 - 5 \\\\ 7 - (-3) \\end{pmatrix}, \\text{ so } \\overrightarrow{AB}\\begin{pmatrix} -7 \\\\ 10 \\end{pmatrix}$$\n\n   and\n\n   $$\\overrightarrow{CD}\\begin{pmatrix} -5 - \\left(-\\dfrac{1}{2}\\right) \\\\ \\dfrac{3}{4} - 0 \\end{pmatrix}, \\text{ so } \\overrightarrow{CD}\\begin{pmatrix} -\\dfrac{9}{2} \\\\ \\dfrac{3}{4} \\end{pmatrix}.$$\n\n   Then work out the scalar product:\n\n   $$\\begin{align}\n   \\overrightarrow{AB} \\cdot \\overrightarrow{CD} &= (-7) \\times \\left(-\\dfrac{9}{2}\\right) + 10 \\times \\dfrac{3}{4} \\\\\n   &= \\dfrac{63}{2} + \\dfrac{30}{4} \\\\\n   &= \\dfrac{126}{4} + \\dfrac{30}{4} \\\\\n   &= \\dfrac{156}{4} \\\\\n   &= 39\n   \\end{align}$$\n2. Work out the components of the vectors $\\overrightarrow{AC}$ and $\\overrightarrow{BD}$:\n\n   $$\\overrightarrow{AC}\\begin{pmatrix} -\\dfrac{1}{2} - 5 \\\\ 0 - (-3) \\end{pmatrix}, \\text{ so } \\overrightarrow{AC}\\begin{pmatrix} -\\dfrac{11}{2} \\\\ 3 \\end{pmatrix}$$\n\n   and\n\n   $$\\overrightarrow{BD}\\begin{pmatrix} -5 - (-2) \\\\ \\dfrac{3}{4} - 7 \\end{pmatrix}, \\text{ so } \\overrightarrow{BD}\\begin{pmatrix} -3 \\\\ -\\dfrac{25}{4} \\end{pmatrix}.$$\n\n   Then work out the scalar product:\n\n   $$\\begin{align}\n   \\overrightarrow{AC} \\cdot \\overrightarrow{BD} &= \\left(-\\dfrac{11}{2}\\right) \\times (-3) + 3 \\times \\left(-\\dfrac{25}{4}\\right) \\\\\n   &= \\dfrac{33}{2} - \\dfrac{75}{4} \\\\\n   &= \\dfrac{66}{4} - \\dfrac{75}{4} \\\\\n   &= -\\dfrac{9}{4}\n   \\end{align}$$\n3. Work out the components of the vectors $\\overrightarrow{AD}$ and $\\overrightarrow{BC}$:\n\n   $$\\overrightarrow{AD}\\begin{pmatrix} -5 - 5 \\\\ \\dfrac{3}{4} - (-3) \\end{pmatrix}, \\text{ so } \\overrightarrow{AD}\\begin{pmatrix} -10 \\\\ \\dfrac{15}{4} \\end{pmatrix}$$\n\n   and\n\n   $$\\overrightarrow{BC}\\begin{pmatrix} -\\dfrac{1}{2} - (-2) \\\\ 0 - 7 \\end{pmatrix}, \\text{ so } \\overrightarrow{BC}\\begin{pmatrix} \\dfrac{3}{2} \\\\ -7 \\end{pmatrix}.$$\n\n   Then work out the scalar product:\n\n   $$\\begin{align}\n   \\overrightarrow{AD} \\cdot \\overrightarrow{BC} &= (-10) \\times \\dfrac{3}{2} + \\dfrac{15}{4} \\times (-7) \\\\\n   &= -\\dfrac{30}{2} - \\dfrac{105}{4} \\\\\n   &= -\\dfrac{60}{4} - \\dfrac{105}{4} \\\\\n   &= -\\dfrac{165}{4}\n   \\end{align}$$"}}'::jsonb, true)
  WHERE id = '6a0166d4-0e80-483a-b339-0d94d849ba74' AND md5(variations::text) = 'e78000acc54e0741eb074613cd5a22fc';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"The triangle ~ABC~ is equilateral with side ~2~ cm. ~I~ is the foot of the altitude from ~A~. \n\n![Capture d’écran 2026 04 22 à 11.43.06](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/geometrie-hehuuubx-1.webp){size=medium align=center}\n\nFind the exact values of the following scalar products.\n\n1. $\\overrightarrow{BC} \\cdot \\overrightarrow{BA}$\n2. $\\overrightarrow{BA} \\cdot \\overrightarrow{BI}$\n3. $\\overrightarrow{AI} \\cdot \\overrightarrow{AC}$","solution_md":"1. ~ABC~ is an equilateral triangle, so $(\\overrightarrow{BC}, \\overrightarrow{BA}) = \\dfrac{\\pi}{3}$. Then\n\n   $$\\begin{align}\n   \\overrightarrow{BC} \\cdot \\overrightarrow{BA} &= \\|\\overrightarrow{BC}\\| \\times \\|\\overrightarrow{BA}\\| \\times \\cos\\left(\\dfrac{\\pi}{3}\\right) \\\\\n   &= 2 \\times 2 \\times \\dfrac{1}{2} \\\\\n   &= 2\n   \\end{align}$$\n2. As ~I~ is the foot of the altitude from ~A~ in the equilateral triangle ~ABC~, it is also the midpoint of the segment $[BC]$, so ~BI=1~ cm.    Moreover, the symmetry of the scalar product gives $\\overrightarrow{BA} \\cdot \\overrightarrow{BI} = \\overrightarrow{BI} \\cdot \\overrightarrow{BA}$, and since $(\\overrightarrow{BI}, \\overrightarrow{BA}) = \\dfrac{\\pi}{3}$, we obtain:\n\n   $$\\begin{align}\\overrightarrow{BA} \\cdot \\overrightarrow{BI} &= \\overrightarrow{BI} \\cdot \\overrightarrow{BA} \\\\\n   &= \\|\\overrightarrow{BI}\\| \\times \\|\\overrightarrow{BA}\\| \\times \\cos\\left(\\dfrac{\\pi}{3}\\right) \\\\\n   &= 1 \\times 2 \\times \\dfrac{1}{2} \\\\\n   &= 1\n   \\end{align}$$\n\n   (Or else $\\overrightarrow{BA} \\cdot \\overrightarrow{BI} = \\overrightarrow{BI} \\cdot \\overrightarrow{BI} = 1^2 = 1$, using the projection).\n3. The line ~(AI)~ is also the bisector of the angle at ~A~ in the triangle ~ABC~, so $(\\overrightarrow{AI}, \\overrightarrow{AC}) = \\dfrac{\\pi}{6}$. To find the length of the segment $[AI]$, use Pythagoras'' theorem in the right-angled triangle ~AIC~:\n\n   $$AC^2 = AI^2 + CI^2$$\n\n   so\n\n   $$AI^2 = AC^2 - CI^2 = 2^2 - 1^2 = 3$$\n\n   and finally ~AI=sqrt(3)~ cm. We then obtain:\n\n   $$\\begin{align}\n   \\overrightarrow{AI} \\cdot \\overrightarrow{AC} &= \\|\\overrightarrow{AI}\\| \\times \\|\\overrightarrow{AC}\\| \\times \\cos\\left(\\dfrac{\\pi}{6}\\right) \\\\\n   &= \\sqrt{3} \\times 2 \\times \\dfrac{\\sqrt{3}}{2} \\\\\n   &= 3\n   \\end{align}$$"}}'::jsonb, true)
  WHERE id = 'a723b0ca-0dad-4cc8-b76c-79db6c40ba2f' AND md5(variations::text) = '964a4adbf71ec7440b9b83cbcca050e2';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Consider the rectangle ~ABCD~ of length ~10~ and width ~6~. ~E~ is the midpoint of the side $[AB]$ and ~F~ the midpoint of the side $[BC]$. \\\n\n\n![Capture d’écran 2026 04 22 à 19.43.37](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/geometrie-5jg5hvsk-3.webp)\n\n\\\nFind the exact values of the following scalar products.\n\n1. $\\overrightarrow{DA} \\cdot \\overrightarrow{DB}$\n2. $\\overrightarrow{DC} \\cdot \\overrightarrow{DF}$\n3. $\\overrightarrow{DA} \\cdot \\overrightarrow{DC}$\n4. $\\overrightarrow{DE} \\cdot \\overrightarrow{DF}$\n5. $\\overrightarrow{DF} \\cdot \\overrightarrow{DB}$","solution_md":"Several methods are of course possible!\n\n1. $\\overrightarrow{DA} \\cdot \\overrightarrow{DB} = \\overrightarrow{DA} \\cdot \\overrightarrow{DA} = 36$, by projecting the point ~B~ onto the segment $[DA]$.\n2. $\\overrightarrow{DC} \\cdot \\overrightarrow{DF} = \\overrightarrow{DC} \\cdot \\overrightarrow{DC} = 100$, by projecting the point ~F~ onto the segment $[DC]$.\n3. $\\overrightarrow{DA} \\cdot \\overrightarrow{DC} = 0$, since ~ABCD~ is a rectangle.\n4. To work out the scalar product $\\overrightarrow{DE} \\cdot \\overrightarrow{DF}$, one may for instance use the orthonormal frame $\\left(A\\,;\\dfrac{1}{10}\\overrightarrow{AB}, \\dfrac{1}{6}\\overrightarrow{AD}\\right)$. The coordinates of the point ~D~ are then $(0\\,;6)$, those of ~E~ are $(5\\,;0)$ and those of ~F~ are $(10\\,;3)$. Work out the components of the vectors $\\overrightarrow{DE}$ and $\\overrightarrow{DF}$ in order to use the coordinate formula for the scalar product:\n\n   $$\\overrightarrow{DE}\\begin{pmatrix} 5 \\\\ -6 \\end{pmatrix} \\text{ and } \\overrightarrow{DF}\\begin{pmatrix} 10 \\\\ -3 \\end{pmatrix}.$$\n\n   Finally,\n\n   $$\\overrightarrow{DE} \\cdot \\overrightarrow{DF} = 5 \\times 10 + (-6) \\times (-3) = 50 + 18 = 68.$$\n5. **Method 1:**In the same way, the coordinates of the point ~B~ are $(10\\,;0)$, so $\\overrightarrow{DB}\\begin{pmatrix} 10 \\\\ -6 \\end{pmatrix}$ and\n\n   $$\\overrightarrow{DF} \\cdot \\overrightarrow{DB} = 10 \\times 10 + (-3) \\times (-6) = 100 + 18 = 118.$$\n\n   **Method 2:**Split the vectors using Chasles'' relation:\n\n   $$\\begin{align*}\\overrightarrow{DF} \\cdot \\overrightarrow{DB} &= (\\overrightarrow{DC} + \\overrightarrow{CF}) \\cdot (\\overrightarrow{DC} + \\overrightarrow{CB}) \\\\\n       &= \\overrightarrow{DC} \\cdot \\overrightarrow{DC} + \\underbrace{\\overrightarrow{DC} \\cdot \\overrightarrow{CB}}_{0} + \\underbrace{\\overrightarrow{CF} \\cdot \\overrightarrow{DC}}_{0} + \\overrightarrow{CF} \\cdot \\overrightarrow{CB} \\\\\n       &= 10 \\times 10 + 3 \\times 6 = 100 + 18 = 118.\\end{align*}$$"}}'::jsonb, true)
  WHERE id = 'b52aeceb-bebc-413f-ae9e-f5bcba4916f6' AND md5(variations::text) = '2eac0026e9f3f0b354883842e0ba7661';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"A company makes pulleys used in the car industry. Assume that the whole output is sold.\n\nThe company can make between $0$ and $3600$ pulleys per week. Let ~x~ be the number of thousands of pulleys made and sold in a week. (So ~x~ varies in the interval $[0~;~3.6]$.) The weekly profit is written ~B(x)~ and is expressed in thousands of euros.\n\nThe aim of this exercise is to study the function ~B~. Parts A and B may be tackled independently of each other.\n\n### Part A: Graphical study\n\nThe function ~B~ is plotted on the axes below.\\\n\n\n![bénéfice entreprise](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/fonctions-a5qwdsj9-2.webp){size=medium align=center caption=\"Weekly profit\"}\n\nGive each answer to the nearest hundred pulleys or the nearest hundred euros, as appropriate.\n\n1. Find the interval in which the number of pulleys must lie for the profit to be at least $13000$ euros.\n2. What is the largest profit the company can expect? For what number ~N~ of pulleys made and sold does it appear to be reached?\n\n### Part B: Algebraic study\n\nThe weekly profit ~B(x)~, in thousands of euros, is given by ~B(x)=-5+(4-x)e^x~.\n\n1.\n   1. Show that for every real ~x~ in the interval $I=[0~;~3.6]$: $B''(x) = (3-x)e^x$.\n   2. Determine the sign of the derivative $B''$ on the interval ~I~.\n   3. Draw up the variation table of the function ~B~ on the interval ~I~. Include the values of ~B~ at the endpoints of the interval.\n2.\n   1. Justify that the equation ~B(x)=13~ has two solutions ~x_1~ and ~x_2~, one in the interval $[0~;~3]$ and the other in the interval $[3~;~3.6]$.\n   2. Using a calculator, find an approximation of each solution to within $0.01$.","solution_md":"### Part A\n\n1. Between $2500$ and $3400$ pulleys must be made and sold for the profit to be at least $13000$ euros.\n2. The largest profit the company can expect is $15000$ €, reached for ~N=3000~ pulleys made and sold.\n\n### Part B\n\n1.\n   1. ~B~ is differentiable on $I=[0~;~3.6]$,\n\n      $$B^{\\prime}(x)=-e^{x}+(4-x)e^{x}=(3-x)e^{x}$$\n   2. $B''(x) > 0 \\Longleftrightarrow x < 3$.\n   3.\n\n      ```variation\n      variable: x\n      domain: 0, 3, 3.6\n      \n      sign: f''(x)\n        0,3: +\n        3: z\n        3,3.6: -\n      \n      variation: f(x)\n        0: -1, bottom\n        3: e^3-5, top\n        3.6: 0.4e^{3.6}-5, bottom\n      ```\n2.\n   1. From the variation table, ~B~ is strictly increasing on $[0;3]$, ~B(0)<13~ and ~B(3)>13~, so the equation ~B(x)=13~ has one solution ~x_1~ in the interval $[0~;~3]$. ~B~ is strictly decreasing on $[3;3.6]$, ~B(3)>13~ and $B(3.6)<13$, so the equation ~B(x)=13~ has one solution ~x_2~ in the interval $[3~;~3.6]$.\n   2. Using a calculator, we obtain $x_1=2.46$ and $x_2=3.4$ to within $0.01$."}}'::jsonb, true)
  WHERE id = '22922f4f-db4e-413a-8d7e-e3f51b78ca5b' AND md5(variations::text) = '98a0ecfbcbbc897fc40438bfac2179d9';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Work in the orthonormal frame $(A\\,;\\overrightarrow{AB}, \\overrightarrow{AC})$. The points ~D~, ~E~ and ~F~ lie on the segments $[AB]$, $[BC]$ and $[CA]$ with ~AD=BE=CF=k~, where $k \\in [0\\,;1]$.  \n\n![Capture d’écran 2026 04 22 à 15.21.56](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/geometrie-e58m48sh-1.webp){size=medium align=center}\n\n 1. Find, in terms of ~k~, the coordinates of the various points of the figure in the frame $(A\\,;\\overrightarrow{AB}, \\overrightarrow{AC})$.    In particular, show that ~E~ has coordinates $\\left(\\dfrac{2 - \\sqrt{2}\\,k}{2}\\,;\\dfrac{\\sqrt{2}\\,k}{2}\\right)$.\n\n2. Work out the scalar product $\\overrightarrow{DE} \\cdot \\overrightarrow{DF}$.\n3. Is there a value of ~k~ for which the triangle ~DEF~ is right-angled at ~D~?","solution_md":"![Capture d’écran 2026 04 22 à 16.45.59](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/geometrie-e58m48sh-2.webp){size=medium align=center}\n\n1. In the frame $(A\\,;\\overrightarrow{AB}, \\overrightarrow{AC})$, we have $A(0\\,;0)$, $B(1\\,;0)$, $C(0\\,;1)$, $D(k\\,;0)$, $F(0\\,;1-k)$.    To find the coordinates of the point ~E~, note that ~ABC~ is a right-angled isosceles triangle, so the angle $\\widehat{ABC} = \\dfrac{\\pi}{4}$. Placing the point ~G~ on the segment $[AB]$ so that the triangle ~EGB~ is right-angled at ~G~, use the trigonometric ratios in the right-angled triangle:\n\n   $$\\sin(\\widehat{GBE}) = \\dfrac{GE}{EB}, \\text{ so } EG = \\sin\\left(\\dfrac{\\pi}{4}\\right) \\times EB = \\dfrac{\\sqrt{2}\\,k}{2}.$$\n\n   Similarly,\n\n   $$\\cos(\\widehat{GBE}) = \\dfrac{GB}{EB} \\text{ so } BG = \\cos\\left(\\dfrac{\\pi}{4}\\right) \\times EB = \\dfrac{\\sqrt{2}\\,k}{2}.$$\n\n   The coordinates of the point ~E~ are therefore $\\left(1 - \\dfrac{\\sqrt{2}\\,k}{2}\\,;\\dfrac{\\sqrt{2}\\,k}{2}\\right)$, that is $\\left(\\dfrac{2 - \\sqrt{2}\\,k}{2}\\,;\\dfrac{\\sqrt{2}\\,k}{2}\\right)$.\n2. Using the coordinates from the previous question, we obtain:\n\n   $$\\overrightarrow{DE}\\begin{pmatrix} \\dfrac{2 - \\sqrt{2}\\,k}{2} - k \\\\ \\dfrac{\\sqrt{2}\\,k}{2} \\end{pmatrix} \\text{ and } \\overrightarrow{DF}\\begin{pmatrix} 0 - k \\\\ 1 - k \\end{pmatrix}$$\n\n   so:\n\n   $$\\begin{align*}\\overrightarrow{DE} \\cdot \\overrightarrow{DF} &= \\left(\\dfrac{2 - \\sqrt{2}\\,k}{2} - k\\right) \\times (-k) + \\dfrac{\\sqrt{2}\\,k}{2} \\times (1 - k) \\\\\n       &= -k + \\dfrac{\\sqrt{2}\\,k^2}{2} + k^2 + \\dfrac{\\sqrt{2}\\,k}{2} - \\dfrac{\\sqrt{2}\\,k^2}{2} \\\\\n       &= k^2 + k\\left(\\dfrac{\\sqrt{2}}{2} - 1\\right) \\\\\n       &= k\\left(k + \\dfrac{\\sqrt{2}}{2} - 1\\right).\\end{align*}$$\n3. The triangle ~DEF~ is right-angled at ~D~ when the scalar product above is zero, that is when ~k=0~ (the triangles ~ABC~ and ~DEF~ then coincide) or when ~k+sqrt(2)/2-1=0~, that is ~k=1-sqrt(2)/2~."}}'::jsonb, true)
  WHERE id = '6dc565e1-2eba-4431-960a-327d3dcf6b6a' AND md5(variations::text) = 'a46a3b32c6e335634630852a70e38c33';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Work inside a square ~ABCD~. The points ~E~, ~F~, ~G~ and ~H~ lie on the sides $[AB]$, $[BC]$, $[CD]$ and $[DA]$ with ~AE=BF=CG=DH=kAB~, where $k \\in [0\\,;1]$. \n\n![Capture d’écran 2026 04 22 à 15.20.08](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/geometrie-zh5qgpeh-2.webp){size=medium align=center}\n\nShow that, whatever the value of ~k~, the quadrilateral ~EFGH~ is a square.","solution_md":"## Method 1\n\nThe ~4~ triangles ~AEH~, ~EBF~, ~FCG~ and ~GDH~ are right-angled triangles of the same dimensions; their sides other than the hypotenuse have lengths ~kAB~ and ~(1-k)AB~. Hence ~EF=FG=GH=HE~, so the quadrilateral ~EFGH~ is a parallelogram, and indeed a rhombus.   Work out the scalar product:\n\n$$\\begin{align*}\\overrightarrow{EF} \\cdot \\overrightarrow{EH} &= (\\overrightarrow{EB} + \\overrightarrow{BF}) \\cdot (\\overrightarrow{EA} + \\overrightarrow{AH}) \\\\\n&= (1 - k)k\\overrightarrow{AB} \\cdot \\overrightarrow{BA} + k(1 - k)\\overrightarrow{BC} \\cdot \\overrightarrow{AD} \\\\\n&= k(k - 1)AB^2 + k(1 - k)AD^2 \\\\\n&= k(k - 1)AB^2 + k(1 - k)AB^2 = 0.\\end{align*}$$\n\nSo the angle $\\widehat{FEB}$ is a right angle, hence ~EFGH~ is a square.\n\n## Method 2: Coordinate geometry\n\nWork in the orthonormal frame $(A\\,;\\overrightarrow{AB}, \\overrightarrow{AD})$. Then $E(k\\,;0)$, $F(1\\,;k)$, $G(1-k\\,;1)$ and $H(0\\,;1-k)$.   The midpoint of the segment $[EG]$ has coordinates $\\left(\\dfrac{1}{2}\\,;\\dfrac{1}{2}\\right)$. Likewise, the midpoint of the segment $[FH]$ has coordinates $\\left(\\dfrac{1}{2}\\,;\\dfrac{1}{2}\\right)$, so the quadrilateral ~EFGH~ is a parallelogram.   Moreover,\n\n$$\\begin{align*}\\overrightarrow{HF} \\cdot \\overrightarrow{EG} &= (\\overrightarrow{HA} + \\overrightarrow{AB} + \\overrightarrow{BF}) \\cdot (\\overrightarrow{EB} + \\overrightarrow{BC} + \\overrightarrow{CG}) \\\\\n&= \\overrightarrow{HA} \\cdot \\overrightarrow{BC} + \\overrightarrow{AB} \\cdot \\overrightarrow{EB} + \\overrightarrow{AB} \\cdot \\overrightarrow{CG} + \\overrightarrow{BF} \\cdot \\overrightarrow{BC} \\\\\n&= (k - 1)AB^2 + (1 - k)AD^2 - kAD^2 + kAB^2 = 0.\\end{align*}$$\n\nSo, as its diagonals are perpendicular, ~EFGH~ is also a rhombus.   Work out the scalar product:\n\n$$\\begin{align*}\\overrightarrow{EF}\\cdot\\overrightarrow{EH} & =(\\overrightarrow{EB}+\\overrightarrow{BF})\\cdot(\\overrightarrow{EA}+\\overrightarrow{AH})\\\\  & =(1-k)k\\overrightarrow{AB}\\cdot\\overrightarrow{BA}+k(1-k)\\overrightarrow{BC}\\cdot\\overrightarrow{AD}\\\\  & =k(k-1)AB^2+k(1-k)AD^2=k(k-1)AB^2+k(1-k)AB^2=0\\end{align*}$$\n\nso the angle $\\widehat{FEB}$ is a right angle, hence ~EFGH~ is a square."}}'::jsonb, true)
  WHERE id = '709bf53b-bf41-4352-8323-4f1e73aa92c7' AND md5(variations::text) = 'b9b7eacbda3a3e77eea884351e5db9dd';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"A treatment protocol for a childhood illness involves a long infusion of a suitable drug. The concentration of the drug in the blood over time is modelled by the function ~C~ defined on the interval $[0~;~+\\infty[$ by: ~C(t)=d/a(1-e^{-a/80t})~\n\nwhere\n\n- ~C~ is the concentration of the drug in the blood, in micromoles per litre,\n- ~t~ is the time elapsed since the start of the infusion, in hours,\n- ~d~ is the infusion rate, in micromoles per hour,\n- ~a~ is a strictly positive real parameter, called the clearance, in litres per hour.\n\nThe parameter ~a~ is specific to each patient.\n\nIn medicine, the “plateau” is the limit of the function ~C~ at ~+\\infty~.\n\n### Part A: A particular case\n\nThe clearance ~a~ of a certain patient is $7$, and an infusion rate ~d~ of $84$ is chosen.\n\nIn this part, the function C is therefore defined on $[0~;~+\\infty[$ by: ~C(t)=12(1-e^{-7/80t})~.\n\n1. Study whether the function ~C~ is increasing or decreasing on $[0~;~+\\infty[$.\n2. To be effective, the plateau must equal $15$. Is this patient''s treatment effective?\n\n### Part B: Studying functions\n\n1. Let ~f~ be the function defined on $]0~;~+\\infty[$ by: ~f(x)=105/x(1-e^{-3/40x})~.    Prove that, for every real ~x~ in $]0~;~+\\infty[$, ~f''(x)={105g(x)}/{x^2}~, where ~g~ is the function defined on $[0~;~+\\infty[$ by:\n\n   ~~g(x)={3x}/40e^{-3/40x}+e^{-3/40x}-1.~~\n2. The variation table of the function ~g~ is given below.\n\n   ```variation\n   variable: x\n   domain: , 0, +inf\n   \n   variation: g(x)\n     0: 0, top\n     +inf: -1, bottom\n   ```\n\n   Hence determine whether the function ~f~ is increasing or decreasing.    *You are not asked for the limits of the function *$f$*.*\n3. Show that the equation $f(x)=5.9$ has exactly one solution on the interval $[1~;~80]$.    Hence deduce that this equation has exactly one solution on the interval $]0~;~+\\infty[$.    Give an approximation of this solution to the nearest tenth.\n\n### Part C: Finding a suitable treatment\n\nThe aim of this part is to find, for a given patient, the infusion rate that makes the treatment effective, that is, that makes the plateau equal to $15$.\n\nFirst, the clearance ~a~ of the patient must be found. To do this, the rate ~d~ is temporarily set to $105$, before working out the rate that makes the treatment effective.\n\nRecall that the function C is defined on the interval $[0~;~+\\infty[$ by: ~C(t)=d/a(1-e^{-a/80t})~\n\n1. We wish to find the clearance a of a patient. The rate is temporarily set to $105$.\n   1. Express, in terms of ~a~, the concentration of the drug $6$ hours after the start of the infusion.\n   2. After $6$ hours, tests give the concentration of the drug in the blood; it equals $5.9$ micromoles per litre.    Find an approximation, to the nearest tenth of a litre per hour, of this patient''s clearance.\n2. Find the infusion rate ~d~ that guarantees the treatment is effective.","solution_md":"### Part A\n\n1. The function ~C~ is differentiable on $[0~;~+\\infty[$ and\n\n$$C^{\\prime}(t)=12\\left(0-\\left(-\\frac{7}{80}\\right)e^{-\\frac{7}{80}t}\\right)=\\frac{21}{20}e^{-\\frac{7}{80}t}>0\\text{ on }[0~;~+\\infty[.$$\n\n   The function ~C~ is therefore strictly increasing on $]0~;~+\\infty[$.\n\n2. The plateau is the limit of the function ~C~ at ~+\\infty~. Using a calculator, we obtain\n\n   $$\\lim_{t\\to+\\infty}C(t)=12.$$\n\n   The plateau should equal $15$. It is only $12$, so the treatment is not suitable.\n\n### Part B\n\n1. The function ~f~ is differentiable on $]0~;~+\\infty[$ as a product of functions differentiable on $]0~;~+\\infty[$, and\n\n   $$\\begin{align*}f''(x) &= 105\\left(-\\frac{1}{x^2}\\right) \\times \\left(1 - e^{-\\frac{3}{40}x}\\right) + \\frac{105}{x} \\times \\left(\\frac{3}{40}e^{-\\frac{3}{40}x}\\right) \\\\\n       &= \\frac{105}{x^2}\\left(-1 + e^{-\\frac{3}{40}x} + \\frac{3x}{40}e^{\\frac{3}{40}}\\right) \\\\\n       &= \\frac{105g(x)}{x^2}\\end{align*}$$\n\n   where ~g~ is the function defined on $[0~;~+\\infty[$ by\n\n   $$g(x)=\\frac{3}{40}x\\exponentialE^{-\\frac{3}{40}x}+\\exponentialE^{-\\frac{3}{40}x}-1$$\n2. ~f''(x)={105g(x)}/{x^2}~, so ~f''(x)~ has the same sign as ~g(x)~ on $]0~;~+\\infty[$.    From the variation table of the function ~g~, ~g(x)<0~, so ~f''(x)<0~ on $]0~;~+\\infty[$.    The function ~f~ is therefore strictly decreasing on $]0~;~+\\infty[$.\n3. From the previous question, the function ~f~ is differentiable and strictly decreasing on $[1~;~80]$.    $f(1)\\approx7.59>5.9$ and $f(80)\\approx1.31<5.9$.    There is therefore a unique real $\\alpha \\in ]1~;~80[$ such that $f(\\alpha)=5.9$.    $f(8.10)\\approx5.902$ and $f(8.11)\\approx5.899$,    so $8.10<\\alpha<8.11$.    Hence $a=8.1$ to the nearest tenth.\n\n### Part C\n\n1.\n   1. Since ~C(t)=105/a(1-e^{-a/80t})~, we have:\n\n      $$C(6)=\\frac{105}{a}\\left(1-e^{-\\frac{a}{80}\\times6}\\right)=\\frac{105}{a}\\left(1-e^{-\\frac{3}{40}a}\\right)=f(a)$$\n\n      from the previous question.\n   2. From the last question of the previous part, the equation $f(a)=5.9$ has a unique solution $a\\approx8.1$.    We therefore take $8.1$ as an approximation of this patient''s clearance ~a~.\n2. We want $\\frac{d}{a}=15\\Longleftrightarrow\\frac{d}{8.1}=15\\Longleftrightarrow d=121.5$.    The rate must therefore be $121.5$ micromoles per hour to give a plateau of $15$, and hence an effective treatment."}}'::jsonb, true)
  WHERE id = 'b35c6751-449c-46df-9814-af2693769eda' AND md5(variations::text) = 'e4bc1f779627971bb8aafa825ab4c9a2';

UPDATE public.exercises SET variations = jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"Let sinh and cosh denote the functions defined for every real ~x~ by: $\\sinh(x) = \\frac{e^x - e^{-x}}{2}$ and $\\cosh(x) = \\frac{e^x + e^{-x}}{2}$.\n\n1. **Studying the function **$\\sinh$\n   1. Show that the function $\\sinh$ is odd.\n   2. Work out the derivative of $\\sinh$ and give its sign.\n   3. Draw up the variation table of the function $\\sinh$ on $[0~;~+\\infty[$.\n   4. Draw up a table of values.\n   5. On orthogonal axes, sketch the graph of the function $\\sinh$ on $[0~;~+\\infty[$. Complete it using a symmetry, which you should state, to obtain the curve$\\mathcal{C}_1$representing $\\sinh$ on $\\mathbb{R}$.\n   6. Determine the sign of $\\sinh(x)$ according to the values of ~x~.\n2. **Studying the function **$\\cosh$\n   1. Show that the function $\\cosh$ is even.\n   2. Work out the derivative of $\\cosh$ and give its sign.\n   3. Draw up the variation table of the function $\\cosh$ on $[0~;~+\\infty[$.\n   4. Draw up a table of values.\n   5. On orthogonal axes, sketch the graph of the function $\\cosh$ on $[0~;~+\\infty[$. Complete it using a symmetry, which you should state, to obtain the curve $\\mathcal{C}_2$ representing $\\cosh$ on $\\mathbb{R}$.\n3. **Relative position of **$\\mathcal{C}_1$** and **$\\mathcal{C}_2$\n   1. Show that for every real ~x~, $\\cosh(x)-\\sinh(x)=e^{-x}$.\n   2. Show that for every real ~x~, $\\cosh(x)>\\sinh(x)$.\n   3. Hence deduce the relative position of the curves $\\mathcal{C}_1$ and $\\mathcal{C}_2$.\n4. **Hyperbolic trigonometric identities**\n   1. Show that for every real ~x~,\n\n      $$(\\cosh(x))^2-(\\sinh(x))^2=1$$\n   2. Show that for all reals ~a~ and ~b~,\n\n      $$\\begin{align*}\\cosh(a + b) &= \\cosh(a)\\cosh(b) + \\sinh(a)\\sinh(b) \\\\\n             \\sinh(a + b) &= \\sinh(a)\\cosh(b) + \\cosh(a)\\sinh(b)\\end{align*}$$\n   3. Hence deduce that for every real ~a~,\n\n      $$\\begin{align*}\\cosh(2a) &= 2(\\cosh(a))^2 - 1 \\\\\n             \\sinh(2a) &= 2\\sinh(a)\\cosh(a)\\end{align*}$$\n   4. Show that for all reals ~p~ and ~q~,\n\n      $$\\begin{align*}\\cosh(p) + \\cosh(q) &= 2\\cosh\\frac{p+q}{2}\\cosh\\frac{p-q}{2} \\\\\n       \\sinh(p) + \\sinh(q) &= 2\\sinh\\frac{p+q}{2}\\cosh\\frac{p-q}{2}\\end{align*}$$"}}'::jsonb, true)
  WHERE id = '859045d6-e567-4294-94c2-6999ea6bea18' AND md5(variations::text) = '89ec6e367f044e5c6ed2cfa19dc4aacf';

UPDATE public.exercises SET variations = jsonb_set(jsonb_set(variations, '{0,translations}', '{"en":{"statement_md":"A lidless box has the shape of a cuboid. Its base is a square of side ~x~ (in metres), with ~x>0~. The volume of the box is $10\\,\\text{m}^3$.\n\n![Lidless box](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/optimisation-6ahh4947-1.png){size=small align=center caption=\"Lidless box\"}\n\nThe base is made from a material costing ~5~ € per square metre, while the side faces are made from a material costing ~2~ € per square metre.\n\nLet ~h~ be the height of the box and ~C~ the cost of making one box.\n\n1. Which interval does the variable $x$ belong to?\n2. Express ~h~ in terms of ~x~.\n3. Show that, for every ~x>0~,\n\n   ~~C(x)={5(x^3+16)}/x~~\n4. Let ~C''~ be the derivative of ~C~. Show that, for every ~x>0~,\n\n   ~~C''(x)={10(x^3-8)}/{x^2}~~\n5. Study how the function ~C~ varies, then find the dimensions of the box for which the cost of making it is least. What is that least cost?","solution_md":"1. The volume of the box is ~V=x^2h~ and ~x~ is positive, so:\n\n   $$x=\\sqrt{\\frac{V}{h}}$$\n\n   As ~h~ tends to $+\\infty$, $x$ tends to ~0~. As ~h~ tends to $0$ , ~x~ tends to $+\\infty$. So $x\\in]0;-\\infty[$.\n2. The volume of the box is ~V=x^2h~, so:\n\n   ~~h=V/{x^2}=10/{x^2}~~\n3. The cost of making the box is given by:\n\n   ~~C(x)=5*x^2+2*4*xh=5x^2+80/x={5(x^3+16)}/x~~\n4. The function ~C~ has the form ~u/v~, so its derivative can be found with the formula ~C''={u''v-v''u}/{v^2}~. This gives:\n\n   $$C''(x)=\\frac{15x^2\\times x - 5x^3 - 80}{x^2}= \\frac{10x^3 - 80}{x^2}$$\n\n   which can also be written:\n\n   ~~C''(x)={10(x^3-8)}/{x^2}~~\n5. The function ~C''~ has the same sign as ~x^3-8~, which is zero when ~x=2~.  This gives the variation table below:\n\n   ```variation\n   variable: x\n   domain: 0, 2, +inf\n   \n   sign: f''(x)\n     0,2: -\n     2: z\n     2,+inf: +\n   \n   variation: f(x)\n     0: +inf, top\n     2: 60, bottom\n     +inf: +inf, top\n   ```\n\n   The cost of making the box is therefore least when ~x=2~, and is then ~60~ euros."}}'::jsonb, true), '{1,translations}', '{"en":{"statement_md":"A lidless box has the shape of a cuboid. Its base is a square of side ~x~ (in metres), with ~x>0~. The volume of the box is $10\\,\\text{m}^3$.\n\n![Lidless box](https://cnevnzsvixxpnurautls.supabase.co/storage/v1/object/public/exercise-images/97c1d5e4-5fa0-44ce-be83-ed5467f3a424/optimisation-6ahh4947-1.png){size=small align=center caption=\"Lidless box\"}\n\nThe base is made from a material costing ~5~ € per square metre, while the side faces are made from a material costing ~2~ € per square metre.\n\nLet ~h~ be the height of the box and ~C~ the cost of making one box.\n\nWhat is the least possible cost of making the box?","solution_md":"The volume of the box is ~V=x^2h~ and ~x~ is positive, so:\n\n$$x=\\sqrt{\\frac{V}{h}}$$\n\nAs ~h~ tends to $+\\infty$, $x$ tends to ~0~. As ~h~ tends to ~0~, ~x~ tends to $+\\infty$. So $x\\in]0;-\\infty[$.\n\nWe also have:\n\n~~h=V/{x^2}=10/{x^2}~~\n\nThe cost of making the box is then given by:\n\n~~C(x)=5*x^2+2*4*xh=5x^2+80/x={5(x^3+16)}/x~~\n\nLet us study how the function $C$ varies:\n\n$$C^{\\prime}(x)=\\frac{15x^2\\times x - 5x^3 - 80}{x^2}=\\frac{10x^3 - 80}{x^2}=\\frac{10 \\left( x^3 - 8 \\right)}{x^2}$$\n\nThe function ~C''~ has the same sign as ~x^3-8~, an increasing function which is zero when ~x=2~.  This gives the variation table below.\n\n```variation\nvariable: x\ndomain: 0, 2, +inf\n\nsign: f''(x)\n  0,2: -\n  2: z\n  2,+inf: +\n\nvariation: f(x)\n  0: +inf, top\n  2: 60, bottom\n  +inf: +inf, top\n```\n\nThe cost of making the box is therefore least when ~x=2~, and is then ~60~ euros."}}'::jsonb, true)
  WHERE id = 'aeb4ce54-1a17-4a95-a293-87336704bea4' AND md5(variations::text) = '0dc3824dcc6e373d090f6ecf512c47bb';

-- Contrôle : 71 variations doivent porter une traduction anglaise.
-- Un compte inférieur signifie que le verrou optimiste a écarté des exercices
-- modifiés depuis la lecture — sans rien écraser, mais il faut le savoir.
DO $$
DECLARE
  traduites integer;
  total integer;
BEGIN
  SELECT count(*) INTO traduites
  FROM public.exercises e, LATERAL jsonb_array_elements(e.variations) v
  WHERE '1_SPE' = ANY(e.grades) AND v ? 'translations';

  SELECT count(*) INTO total
  FROM public.exercises WHERE '1_SPE' = ANY(grades);

  IF total = 0 THEN
    -- Cas local : la base ne contient pas ces exercices, la migration est un
    -- no-op attendu. Ne pas confondre avec un verrou md5 qui aurait mordu.
    RAISE NOTICE 'Traductions 1re spe : aucun exercice de 1re spe dans cette base, rien a traduire.';
  ELSIF traduites = 71 THEN
    RAISE NOTICE 'Traductions 1re spe : 71/71 variations traduites.';
  ELSE
    RAISE WARNING 'Traductions 1re spe : % variation(s) traduite(s) sur 71 attendues. Les exercices modifies depuis le 2026-09-03 ont ete ecartes par le verrou md5 : rien n a ete ecrase, mais ils restent en francais.', traduites;
  END IF;
END $$;
